package com.ninho.account;
import com.ninho.shared.*;import java.util.*;import java.time.*;import java.nio.charset.StandardCharsets;import java.security.*;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.dao.DuplicateKeyException;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.oauth2.jwt.*;import org.springframework.security.oauth2.jose.jws.SignatureAlgorithm;
@Service public class AccountService {
 private final JdbcTemplate db;private final JwtEncoder encoder;private final BCryptPasswordEncoder passwords=new BCryptPasswordEncoder(11);private final String dummyHash=passwords.encode("ninho-nonexistent-account");private final SecureRandom random=new SecureRandom();
 public AccountService(JdbcTemplate db,JwtEncoder encoder){this.db=db;this.encoder=encoder;}
 public Object readiness(){db.queryForObject("SELECT 1",Integer.class);return Map.of("available",true);}
 public record SignedIn(Map<String,Object>user,String access,String refresh){}
 static String hash(String token){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(token.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private Map<String,Object> user(UUID id){var rows=db.query("SELECT id,name,email,age FROM app_user WHERE id=?",(r,n)->Map.<String,Object>of("id",r.getObject("id",UUID.class),"name",r.getString("name"),"email",r.getString("email"),"age",r.getInt("age")),id);if(rows.isEmpty())throw DomainException.missing();return rows.getFirst();}
 private String access(UUID id,String name,UUID session){var now=Instant.now();var claims=JwtClaimsSet.builder().issuer("ninho-local").subject(id.toString()).audience(List.of("ninho-services")).issuedAt(now).expiresAt(now.plusSeconds(900)).id(session.toString()).claim("name",name).build();return encoder.encode(JwtEncoderParameters.from(JwsHeader.with(SignatureAlgorithm.RS256).keyId("ninho-local").build(),claims)).getTokenValue();}
 private SignedIn createSession(UUID id){byte[]bytes=new byte[32];random.nextBytes(bytes);String refresh=Base64.getUrlEncoder().withoutPadding().encodeToString(bytes);UUID session=UUID.randomUUID();long now=System.currentTimeMillis();db.update("INSERT INTO app_session(id,user_id,refresh_hash,expires_at,created_at) VALUES(?,?,?,?,?)",session,id,hash(refresh),now+604800000,now);var user=user(id);return new SignedIn(user,access(id,(String)user.get("name"),session),refresh);}
 @Transactional public SignedIn register(String name,String email,String password,int age,String petName,int color,String accessory,String environment){validateAppearance(color,accessory,environment);if(password.getBytes(StandardCharsets.UTF_8).length>72)throw DomainException.invalid("Essa senha é muito longa. Escolha uma menor.");UUID id=UUID.randomUUID();try{db.update("INSERT INTO app_user(id,name,email,password_hash,age,created_at) VALUES(?,?,?,?,?,?)",id,name.trim(),email.trim().toLowerCase(Locale.ROOT),passwords.encode(password),age,System.currentTimeMillis());}catch(DuplicateKeyException e){throw new DomainException(409,"EMAIL_IN_USE","Esse e-mail já tem um ninho. Entre com a senha dessa conta para continuar.");}db.update("INSERT INTO pet_profile(user_id,pet_name,pet_color,accessory,environment,voice,reduced_motion) VALUES(?,?,?,?,?,?,?)",id,petName.trim(),color,accessory,environment,false,false);return createSession(id);}
 @Transactional public SignedIn login(String email,String password){var rows=db.queryForList("SELECT id,password_hash FROM app_user WHERE email=?",email.trim().toLowerCase(Locale.ROOT));String stored=rows.isEmpty()?dummyHash:(String)rows.getFirst().get("password_hash");if(password.getBytes(StandardCharsets.UTF_8).length>72||!passwords.matches(password,stored)||rows.isEmpty())throw new DomainException(401,"INVALID_CREDENTIALS","Confira seu e-mail e sua senha.");return createSession((UUID)rows.getFirst().get("id"));}
 @Transactional public SignedIn refresh(String token){if(token==null||token.length()>150)throw new DomainException(401,"SESSION_EXPIRED","Entre novamente para continuar.");var sessions=db.queryForList("SELECT id,user_id FROM app_session WHERE refresh_hash=? AND expires_at>?",hash(token),System.currentTimeMillis());if(sessions.isEmpty())throw new DomainException(401,"SESSION_EXPIRED","Entre novamente para continuar.");var session=sessions.getFirst();var user=user((UUID)session.get("user_id"));return new SignedIn(user,access((UUID)user.get("id"),(String)user.get("name"),(UUID)session.get("id")),token);}
 public void logout(String token){if(token!=null)db.update("DELETE FROM app_session WHERE refresh_hash=?",hash(token));}
 public Object me(Jwt jwt){if(jwt==null)return Collections.singletonMap("user",null);UUID id=UUID.fromString(jwt.getSubject());if(db.queryForObject("SELECT COUNT(*) FROM app_session WHERE id=? AND user_id=? AND expires_at>?",Integer.class,UUID.fromString(jwt.getId()),id,System.currentTimeMillis())==0)throw new DomainException(401,"SESSION_EXPIRED","Entre novamente para continuar.");return Map.of("user",user(id),"profile",profile(id));}
 public Map<String,Object> profile(UUID id){var rows=db.query("SELECT p.*,u.name,u.age FROM pet_profile p JOIN app_user u ON u.id=p.user_id WHERE p.user_id=?",(r,n)->Map.<String,Object>of("userDisplayName",r.getString("name"),"userAge",r.getInt("age"),"petName",r.getString("pet_name"),"petColor",r.getInt("pet_color"),"accessory",r.getString("accessory"),"environment",r.getString("environment"),"preferences",Map.of("voice",r.getBoolean("voice"),"reducedMotion",r.getBoolean("reduced_motion"))),id);if(rows.isEmpty())throw DomainException.missing();return rows.getFirst();}
 @Transactional public Object updateProfile(UUID id,String name,int age,String pet,int color,String accessory,String environment,boolean voice,boolean motion){validateAppearance(color,accessory,environment);db.update("UPDATE app_user SET name=?,age=? WHERE id=?",name.trim(),age,id);if(db.update("UPDATE pet_profile SET pet_name=?,pet_color=?,accessory=?,environment=?,voice=?,reduced_motion=? WHERE user_id=?",pet.trim(),color,accessory,environment,voice,motion,id)==0)throw DomainException.missing();return profile(id);}
 private static void validateAppearance(int color,String accessory,String environment){if(color<0||color>2||!Set.of("leaf","bow","star").contains(accessory)||!Set.of("garden","dusk","night").contains(environment))throw DomainException.invalid("Escolha uma aparência disponível para seu ninho.");}
 @Transactional public Object presence(UUID id,String kind){if(!Set.of("welcome","care","message","choice","activity","cast","catch","fish-choice","rest-memory","weather","peer-message").contains(kind))throw DomainException.invalid("Essa ação não confirma presença.");long now=System.currentTimeMillis();if(db.update("UPDATE presence_event SET last_seen_at=?,last_action=? WHERE user_id=?",now,kind,id)==0)db.update("INSERT INTO presence_event(user_id,last_seen_at,last_action) VALUES(?,?,?)",id,now,kind);return Map.of("received",true,"at",now,"deliveryEnabled",false);}
 public Object memories(UUID id){return Map.of("items",db.query("SELECT id,kind,created_at FROM memory WHERE user_id=? ORDER BY created_at DESC",(r,n)->Map.of("id",r.getObject("id",UUID.class),"kind",r.getString("kind"),"createdAt",r.getLong("created_at")),id));}
 @Transactional public Object remember(UUID user,UUID id,String kind){if(!Set.of("sunfish","moonfish","mintfish","coralfish","rest","soup","cookies","park-lake","park-flowers").contains(kind))throw DomainException.invalid("Essa lembrança não está disponível.");db.queryForObject("SELECT id FROM app_user WHERE id=? FOR UPDATE",UUID.class,user);var existing=db.queryForList("SELECT user_id FROM memory WHERE id=?",id);if(!existing.isEmpty()){if(!user.equals(existing.getFirst().get("user_id")))throw DomainException.missing();return Map.of("saved",true);}db.update("INSERT INTO memory(id,user_id,kind,created_at) VALUES(?,?,?,?)",id,user,kind,System.currentTimeMillis());return Map.of("saved",true);}
 public void removeMemory(UUID user,UUID id){db.update("DELETE FROM memory WHERE user_id=? AND id=?",user,id);}
}